export function getQuoteRef(id: string): AcademyQuoteRef | undefined {
  return ACADEMY_QUOTE_REFS.find((q) => q.id === id);
}

export interface AcademyLesson {
  id: string;
  index: number;
  /** 所屬卷:課程按學習路徑分卷,新課入返所屬卷,唔再 append 喺尾。 */
  track: AcademyTrackId;
  title: string;
  sub: string;
  minutes: number;
  sections: AcademySection[];
  quiz: AcademyQuizQ[];
  /** 延伸出處:每課 2–4 個已核實的公有領域原文鏈接。 */
  sources: AcademySource[];
  /** 互動組件:在 widgetAfter 指定的 section 之後渲染;-1 = 放在第一節之前(圖先行,先看圖再讀字)。 */
  widget?: "palm" | "bagua" | "jiugong" | "baxing" | "shouji" | "abcde";
  widgetAfter?: number;
}

/** 課程分卷(學習路徑):根基 → 占卦實務 → 工具與專題。 */
export type AcademyTrackId = "foundations" | "practice" | "tools" | "fengshui" | "xiangfa" | "names" | "living" | "mind" | "daoyi";

export interface AcademyTrack {
  id: AcademyTrackId;
  no: string;
  title: string;
  sub: string;
}

export const ACADEMY_TRACKS: AcademyTrack[] = [
  { id: "foundations", no: "第一卷", title: "根基", sub: "陰陽、八卦與數的源頭" },
  { id: "practice", no: "第二卷", title: "占卦實務", sub: "由讀卦、問卦到解卦" },
  { id: "tools", no: "第三卷", title: "工具與專題", sub: "隨身工具與進階題目" },
  { id: "fengshui", no: "第四卷", title: "風水", sub: "九宮、方位與居家調整" },
  { id: "xiangfa", no: "第五卷", title: "相法", sub: "面相、手相與五行人" },
  { id: "names", no: "第六卷", title: "姓名", sub: "名字陰陽與選字之道" },
  { id: "living", no: "第七卷", title: "生活應用", sub: "手機、頭像、穿衣與改運" },
  { id: "mind", no: "第八卷", title: "心理與心法", sub: "心理學與修心之法" },
  { id: "daoyi", no: "第九卷", title: "道醫與養生", sub: "傳統醫理框架與養生(只講原理)" },
];

export function getTrack(id: AcademyTrackId): AcademyTrack {
  return ACADEMY_TRACKS.find((t) => t.id === id) ?? ACADEMY_TRACKS[0];
}

