          "《繫辭》載：「天一地二，天三地四，天五地六，天七地八，天九地十」一三五七九為天數（陽），二四六八十為地數（陰）。再配以方位：一六在北屬水，二七在南屬火，三八在東屬木，四九在西屬金，五十居中屬土——此即五行生成數，後世八字論五行旺衰，根源在此。",
          "伏羲更進一步，將陰陽兩爻三疊，畫出八卦（乾☰、兌☱、離☲、震☳、巽☴、坎☵、艮☶、坤☷）。故云河圖為易經之源：由數見陰陽，由陰陽見八卦。",
