          "此九數有一神奇特性：橫、直、斜三數相加，恆等於十五。古人以為，此非巧合，而是宇宙運行的節奏——九個位置，九種氣，周流不息。後世的九宮飛星，即將此九數套入時間與方位，推算吉凶。",
          "《尚書·洪範》載：「天乃錫禹洪范九疇」大禹由洛書悟出治國九綱（五行、五事、八政、五紀、皇極、三德、稽疑、庶徵、五福六極），箕子後向周武王陳述之，遂成儒家政治哲學源頭之一。一龜之背，承載自命理以至治國的整套世界觀。",
