          "《周易》位列儒家五經之首：詩、書、禮、易、春秋。道之光《天眼風水師》第一〇四章借一場閒談點出這個常被忽略的事實：書店裡最常見的《周易》，大部分篇幅其實是傳文。換言之，我們今天讀到的易學，骨子裡經過儒家思想的整理與轉化——它不只是一本占卜手冊，更是一部講變化之理的經典。",
