          "這個比例值得初學者牢記。易學在傳統中的用途，從來包括修辭、決策、工藝與哲學，占斷只是其中一條支流。後世術數——風水、命理、占卜——皆從這套符號與義理中分化而出；回到源頭看，易學首先是一門如何理解變化的學問，其次才是一門預測的技術。",
