        "正確的次第是先通原理，再臨場推理。懂了風如何成煞，見到任何格局都能自行判斷風往哪裡擠、哪裡加速；懂了後文九宮砂水的平衡法，見到任何物品都能按其高低、動靜、火水屬性歸類。原理是有限的，條目是無窮的；以有限的原理應付無窮的變化，才是這門學問真正的用法。本書後續各課——砂水、逐宮、形煞——走的都是這條路。",
