        "拆字是傳統讀字法的一種，著眼點不在斷言吉凶，而在提醒選字者：一個字除了字典裡的意思，還有它呈現在眼前的形狀。字形中藏著刀兵、殘缺、傾斜等部件，縱然字義再好，也值得多一分斟酌。學會拆字，等於多了一副檢查名字的眼睛；至於拆出的意象如何取捨，仍應回到字義與整體而定，不可憑一字之拆而全盤否定。",
