        "道之光《天眼風水師》第一六九章講了一個心理學實驗。研究者把受試者隨機分成三組，用二十天時間練習籃球投籃：第一組每天實際練習；第二組完全不練；第三組不碰籃球，只在腦海中想像自己投籃，每天二十分鐘。二十天後測量成績：實際練習的一組進步約百分之二十四，完全不練的一組沒有變化，而只在腦中練習的一組，進步幅度竟然與實際練習的一組相近。",
        "書中把這個現象稱為布利斯效應，又叫布利斯定理，第三組所做的事，則被稱為頭腦熱身。這個實驗的數字在流傳中或有出入，後世運動心理學的研究結論也較為審慎：心理演練的提升作用普遍獲得肯定，但多被視為實際練習的補充而非替代。儘管如此，實驗揭示的方向是清楚的：行動尚未發生之前，大腦中的排演，已經在改變行動的質素。",
        "這一點與中國傳統的預習觀念遙相呼應。《禮記》有言：『凡事預則立，不預則廢』；《孫子兵法》亦講多算勝、少算不勝。古人所謂的預與算，落到現代心理學的語言裡，正是行動之前的模擬與演練。布利斯效應的價值，不在於提供一條偷懶的捷徑，而在於指出：準備工作有很大一部分，可以在腦中先行完成。",
