        "想像結果之所以作用有限，是因為結果本身不包含任何操作資訊。大腦無法從一幅成功的畫面中，學會手腕該如何發力。反之，過程演練把一連串動作拆開來逐格播放：站位、屈膝、舉球、出手、隨球動作，每一步的力度與節奏都在腦中過一遍。這等於在神經系統裡先把動作的路線圖畫好，真正上場時，身體只需沿著熟悉的路線執行。",
        "因此，判斷自己的心理演練是否到位，有一個簡單的標準：想像的畫面裡，有沒有具體的、可感知的動作細節。如果只有歡呼與掌聲，那是結果想像；如果能感受到球的重量、手指的觸感、肌肉的鬆緊，那才是過程演練。前者是願望，後者是訓練。",
