        "其次，演練能降低臨場的陌生感與焦慮。人在面對做過許多遍的事情時，自然鎮定；面對全然陌生的場面，則容易緊張失措。心理演練等於在安全的環境中預先經歷事件的流程：哪一步容易出錯、哪裡需要停頓、出錯後如何補救，都先在腦中走過。真正面對時，大腦會產生一種似曾相識的穩定感，注意力便能從應付慌亂，轉回任務本身。",
