        "這正是布利斯效應在日常生活中的正確讀法。心理演練從來不是意念致動，它的效果要經過行動這一關：腦中的排演讓人更清楚該做什麼、更有信心去做、做起來更少慌亂，最終由真實的行動產生真實的結果。若抽掉行動，只剩下想像，效應便無從落地。",
