        "信念有理性與非理性之分。理性的信念是偏好式的：我希望事情順利，不順利我會失望，但可以接受、可以想辦法。非理性的信念則帶有絕對化的口吻，艾利斯歸納出幾種常見形態。其一是絕對化的要求：事情必須如我所願、別人必須公平待我、我必須表現出色，願望被說成了不容違抗的命令。其二是糟糕至極的評價：一旦不如意，便認定這是百分之百的壞事、是災難，再無任何好處。其三是低挫折容忍：我受不了、我無法忍受，把不舒服誇大為不可承受。其四是以偏概全的整體評價：由一件事的成敗，判定自己或他人整個人一無是處。",
        "這些信念的共同點，是把偏好升級為必然、把不如意升級為災難。事件本身往往只是不便或遺憾，經過絕對化信念的放大，才變成強烈的情緒風暴。考試失手本是一次結果，若信念是我必須成功、失敗就證明我毫無價值，隨之而來的便不只是失望，還會有羞恥與自我否定。",
        "辨認非理性信念，可以留意語言中的訊號：必須、應該、絕對、受不了、完了、徹底失敗。當這些字眼在心中出現，往往就是 B 正在把一件普通的不如意，加工成一場情緒危機。認出它，不等於立刻不難受，但已經是把主動權拿回來的開始。",
