        "認出非理性信念之後，第四步 D 是質疑（Disputing）：像辯論一樣，與原有信念正面交鋒，重新解讀事件。質疑通常沿三個方向進行。經驗之問：有什麼證據支持這個想法？他批評我一句，是否等於他全盤否定我？邏輯之問：從這件事推出那個結論，中間是否跳了步？一次失手，邏輯上推不出我永遠不行。實用之問：抱著這個信念，對我究竟有什麼好處？它讓我更能解決問題，還是只讓我更痛苦、更想逃避？三問之下，絕對化的信念往往站不住腳。",
        "經過質疑，便來到第五步 E，新效果（Effect）：以較理性、較有彈性的信念取代舊信念，產生新的情緒與行為。新信念不是盲目樂觀的自我安慰，而是把必須改回偏好：我很希望做好，這次沒做好，我失望，但這不定義我這個人，我可以檢討方法再試。情緒也隨之從崩潰式的焦慮、羞恥，回到適度的失望與在意——後者雖不愉快，卻能推動行動而非癱瘓行動。",
