        "兩者的相通，也提醒我們重新解讀的分寸。陰陽雙面解讀不是把壞事硬說成好事，而是承認一件事本就有多個面向，情緒只跟住其中一面時，人便被那一面困住。質疑舊信念的過程，就是把被忽略的另一面找回來，讓評價回到完整與平衡。這與本學院一以貫之的態度相同：不迷信單一解讀，不被單一情緒牽引。",
